Builds a two-item outline tree (one with a nested child) with Document.SetOutlines across three pages added with Document.AddPage, writes and reopens the document, and reads the surviving titles, nesting and page destination back with Document.GetOutlines.

Example:
// Authored example: set a two-level bookmark outline on a document, save and reload, and read the outline back.
import { Document, PageFormat } from "@asposefoss/pdf";

function main(): void {
  const doc = Document.New(PageFormat.A4);
  doc.AddPage(PageFormat.A4);
  doc.AddPage(PageFormat.A4);

  doc.SetOutlines([
    {
      Title: "Chapter 1",
      Dest: { page: 1 },
      Children: [{ Title: "Section 1.1", Dest: { page: 2 } }],
    },
    { Title: "Chapter 2", Dest: { page: 3 } },
  ]);

  const path = "outputfiles/cand4.pdf";
  doc.WriteTo(path);

  const reloaded = Document.OpenFile(path);
  const outlines = reloaded.GetOutlines();
  console.log("outline titles:", outlines.map((item) => item.Title));

  if (outlines.length !== 2) throw new Error(`expected 2 top-level outline items, got ${outlines.length}`);
  if (outlines[0].Title !== "Chapter 1") throw new Error(`expected first title Chapter 1, got ${outlines[0].Title}`);
  if (outlines[1].Title !== "Chapter 2") throw new Error(`expected second title Chapter 2, got ${outlines[1].Title}`);
  const children = outlines[0].Children ?? [];
  if (children.length !== 1 || children[0].Title !== "Section 1.1") {
    throw new Error(`expected one child titled Section 1.1, got ${JSON.stringify(children)}`);
  }
  const firstDest = outlines[0].Dest;
  if (!firstDest || !("page" in firstDest) || firstDest.page !== 1) {
    throw new Error(`expected Chapter 1 to point at page 1, got ${JSON.stringify(firstDest)}`);
  }
  console.log("cand4 OK");
}

main();
