Example:
// Authored example: add a sticky note and a highlight annotation to a page, save and reload, and read both back.
import { Document, PageFormat, TextAnnotation, MarkupAnnotation } from "@asposefoss/pdf";

function main(): void {
  const doc = Document.New(PageFormat.A4);
  const page = doc.Pages[0];

  page.AddTextNote({ rect: [400, 760, 424, 784], contents: "Check these numbers", icon: "Comment" });
  page.AddHighlight({ quads: [72, 740, 200, 740, 72, 726, 200, 726], color: [1, 1, 0], contents: "important total" });

  const path = "outputfiles/cand3.pdf";
  doc.WriteTo(path);

  const reloaded = Document.OpenFile(path);
  const annotations = reloaded.Pages[0].Annotations;
  console.log("annotation count:", annotations.length, "subtypes:", annotations.map((a) => a.Subtype));

  if (annotations.length !== 2) throw new Error(`expected 2 annotations, got ${annotations.length}`);
  const note = annotations.find((a) => a instanceof TextAnnotation);
  const highlight = annotations.find((a) => a instanceof MarkupAnnotation);
  if (!note) throw new Error("expected a TextAnnotation (sticky note) after reload");
  if (!highlight) throw new Error("expected a MarkupAnnotation (highlight) after reload");

  if (note.Contents !== "Check these numbers") throw new Error(`unexpected note contents: ${note.Contents}`);
  if (highlight.Contents !== "important total") throw new Error(`unexpected highlight contents: ${highlight.Contents}`);
  console.log("cand3 OK");
}

main();
